-- init_vectors.sql
-- Shared post-gendata setup for Percona/MySQL (executor1) and MariaDB (executor2).
--
-- Compare-mode requirements:
--   1. DROP + CREATE + explicit primary-key IDs (no AUTO_INCREMENT).
--   2. All v384 values are genuine 384-element vectors (MariaDB rejects under-width
--      VECTOR(384) payloads that Percona may accept) so both servers load the same
--      8 rows: ids 1,2,3,4,5,10,20,50.
--   3. Literal constructors are dialect-tagged:
--        /*executor1 STRING_TO_VECTOR */ /*executor2 VEC_FromText */
--
-- Under-width / dim-mismatch edge cases belong in a dedicated error_handling
-- grammar/validator, not in this shared compare seed.

DROP TABLE IF EXISTS test.vt;

CREATE TABLE test.vt (
    id INT PRIMARY KEY,
    label VARCHAR(32),
    category VARCHAR(32),
    v3 VECTOR(3),
    v8 VECTOR(8),
    v384 VECTOR(384),
    v4_baseline VECTOR(4),
    v4_anomaly_a VECTOR(4),
    v4_anomaly_b VECTOR(4)
);

-- ids 1, 2: same metadata/vectors as the original seed rows for v3/v8/v4_*,
-- but v384 is a full 384-element vector (same payload as id 3) so MariaDB
-- accepts the INSERT. Explicit `id` values — no AUTO_INCREMENT.
